package com.kerisprayerflash;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

class KerisPrayerFlashOverlay extends WidgetItemOverlay
{
    static final int PRAYER_THRESHOLD = 50;
    private static final int PULSE_PERIOD_MS = 900;
    private static final Color SAFE_COLOR = new Color(35, 255, 80);
    private static final Color LOW_COLOR = new Color(255, 35, 35);

    private final Client client;
    private final ItemManager itemManager;

    @Inject
    KerisPrayerFlashOverlay(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;

        // Deliberately target only the normal inventory interface. Equipment,
        // bank, trade, shop, and other item interfaces are not registered.
        showOnInterfaces(InterfaceID.INVENTORY);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (itemId != ItemID.KERIS_PARTISAN_SUN)
        {
            return;
        }

        int prayer = client.getBoostedSkillLevel(Skill.PRAYER);
        Color color = isPrayerAtOrAboveThreshold(prayer) ? SAFE_COLOR : LOW_COLOR;
        Image tint = ImageUtil.fillImage(itemManager.getImage(itemId), color);
        Rectangle bounds = widgetItem.getCanvasBounds();

        Graphics2D pulseGraphics = (Graphics2D) graphics.create();
        try
        {
            pulseGraphics.setComposite(AlphaComposite.SrcOver.derive(pulseAlpha(System.currentTimeMillis())));
            pulseGraphics.drawImage(tint, bounds.x, bounds.y, null);
        }
        finally
        {
            pulseGraphics.dispose();
        }
    }

    static boolean isPrayerAtOrAboveThreshold(int prayer)
    {
        return prayer >= PRAYER_THRESHOLD;
    }

    static float pulseAlpha(long nowMs)
    {
        double phase = (nowMs % PULSE_PERIOD_MS) / (double) PULSE_PERIOD_MS;
        double wave = (Math.sin(phase * Math.PI * 2.0) + 1.0) / 2.0;
        return (float) (0.25 + 0.75 * wave);
    }
}

package com.kerisprayerflash;

import javax.inject.Inject;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "TOA Keris Reminder",
    description = "Don't panic - your Keris flashes green at 50+ Prayer and red below 50",
    tags = {"keris", "prayer", "inventory", "highlight", "toa"}
)
public class KerisPrayerFlashPlugin extends Plugin
{
    @Inject
    private OverlayManager overlayManager;

    @Inject
    private KerisPrayerFlashOverlay overlay;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
    }
}

package com.kerisprayerflash;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class KerisPrayerFlashOverlayTest
{
    @Test
    public void thresholdIncludesFifty()
    {
        assertFalse(KerisPrayerFlashOverlay.isPrayerAtOrAboveThreshold(49));
        assertTrue(KerisPrayerFlashOverlay.isPrayerAtOrAboveThreshold(50));
        assertTrue(KerisPrayerFlashOverlay.isPrayerAtOrAboveThreshold(51));
    }

    @Test
    public void pulseAlwaysUsesAVisibleValidAlpha()
    {
        for (long nowMs = 0; nowMs < 2_000; nowMs += 10)
        {
            float alpha = KerisPrayerFlashOverlay.pulseAlpha(nowMs);
            assertTrue(alpha >= 0.25f);
            assertTrue(alpha <= 1.0f);
        }
    }
}

package com.kerisprayerflash;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public final class KerisPrayerFlashPluginLauncher
{
    private KerisPrayerFlashPluginLauncher()
    {
    }

    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(KerisPrayerFlashPlugin.class);
        RuneLite.main(args);
    }
}
